+l000: label(name:"bug"){id,name}
+l001: label(name:"help wanted"){id,name}
+}
+organization(login:"OWNER"){
+t000: team(slug:"core"){id,slug}
+t001: team(slug:"robots"){id,slug}
+}
+}
+`
+	responseJSON := `
+	{ "data": {
